// -*- coding: utf-8 -*-
#pragma once
//
// Shared helpers for the two-level CA corpus at tests/fixtures/crl_chain/
// (generated by tests/fixtures/gen_two_level_ca_signer.py).
//
// WHY THIS HEADER EXISTS
// ----------------------
// Phase-48 built the corpus and used it from ONE test file. The phase-48
// security review's SEC-9 finding was that three CRL tests in
// tests/test_ocsp_crl_validation.cpp and one in tests/test_encrypt_ocsp_phase3.cpp
// still minted their CRLs from tests/fixtures/test_signer.pfx — a self-signed
// END-ENTITY certificate with no cRLSign — and every one of them ran with
// useTrustAnchors=false, so their verdict was UntrustedChain and their
// `EXPECT_NE(..., LtvValidated)` could not fail for ANY input. The named rules
// ("expired CRL rejected", "expired CRL is not revocation evidence") were
// vacuous before phase-48 and doubly masked after it.
//
// Migrating them onto the real chain is the fix, and that needs the same six
// helpers the original file grew. Copying them would reproduce this
// programme's most recurring defect shape — a fix that leaves the sibling one
// file over untouched — so they live here instead, and every user shares one
// definition.
//
// Everything is `inline` because this header is included by more than one
// translation unit.

#include <gtest/gtest.h>

#include "signatures/SignatureManager.h"
#include "signatures/TrustAnchorManager.h"
#include "core/Document.h"
#include "core/MuPdfContext.h"
